SELECT HOUR(txn_time) AS txn_hour, CASE WHEN amount >= 3900 THEN 'high' WHEN amount >= 1200 THEN 'mid' ELSE 'low' END AS amount_bucket, merchant, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(txn_type))) AS txn_type_values, COUNT(amount) AS amount_count, MIN(txn_time) AS first_txn_time FROM transactions WHERE merchant = 'Starbucks' AND merchant <> '7-Eleven' GROUP BY 1, 2, 3 HAVING COUNT(amount) > 1 ORDER BY amount_count DESC, txn_hour, amount_bucket, merchant LIMIT 1
